# numbers_certgap.jl: the macros of figures/fig_certgap.pdf (results/fig_certgap_data.json, HPG runs E63, E65b,
# E69, E106, E112), the certificate eta of Lemma lem:cert against the true gap of the team plan, written to
# preamble/numbers_certgap.tex. Not registered with gen_numbers.jl; main.tex inputs the generated file with
# \InputIfFileExists.
#
# Identical (gap, eta) pairs within a group are counted once (E112 repeats samples across its arms). Samples whose
# true gap is below GAP_FLOOR times V_N^0 are then dropped: the solver tolerance is 1e-6, so a ratio of gaps below
# 1e-5 measures solver noise. render/fig_certgap.py applies the same dedup and cut. Quantiles are order statistics, q(a) = sorted[ceil(a * n)].
#
#   julia --project=env scripts/resolution/numbers_certgap.jl

using JSON, Printf

const GAP_FLOOR = 1e-5
const GROUPS = [("E63", "Rand"), ("E69", "Incons"), ("E112", "Refine"), ("E106", "Big")]

function sci(x; d = 1)
    x == 0 && return "0"
    e = floor(Int, log10(abs(x))); m = x / 10.0^e
    s = @sprintf("%.*f", d, m)
    if parse(Float64, s) >= 10; m /= 10; e += 1; s = @sprintf("%.*f", d, m); end
    return "\\ensuremath{$(s)\\times10^{$(e)}}"
end
sig(x; n = 3) = (s = @sprintf("%.*g", n, x); occursin("e", s) ? sci(x) : s)
q(srt, a) = srt[clamp(ceil(Int, a * length(srt)), 1, length(srt))]

function write_certgap_numbers(root = normpath(joinpath(@__DIR__, "..", "..")))
    D = JSON.parsefile(joinpath(root, "results", "fig_certgap_data.json"))["groups"]
    lines = String["% GENERATED by scripts/resolution/numbers_certgap.jl from results/fig_certgap_data.json; do not edit by hand.",
                   "% Regenerate with `julia --project=env scripts/resolution/numbers_certgap.jl`.", ""]
    put(name, val, meaning) = (push!(lines, "% $meaning"); push!(lines, "\\newcommand{\\$name}{$val}"))
    put("cnCgFloor", sci(GAP_FLOOR; d = 0), "samples with gap below this times V_N^0 are dropped")
    all_r = Float64[]; raw = 0; uniq = 0; below = 0
    for (k, M) in GROUPS
        g0 = Float64.(D[k]["gap_rel"]); e0 = Float64.(D[k]["eta_rel"])
        P = unique(collect(zip(g0, e0))); g = first.(P); e = last.(P)
        keep = g .>= GAP_FLOOR; r = sort(e[keep] ./ g[keep])
        raw += length(g0); uniq += length(g); append!(all_r, r); below += count(<(1), r)
        put("cnCg$(M)Dup", string(length(g0) - length(g)), "$k: repeated (gap, eta) pairs removed")
        put("cnCg$(M)Dropped", string(length(g) - length(r)), "$k: distinct samples dropped by the gap floor")
        put("cnCg$(M)Pnn", sig(q(r, 0.99)), "$k: eta / gap, 99th percentile")
        put("cnCg$(M)AboveTwo", sig(100 * count(>(2), r) / length(r); n = 2), "$k: percent of kept samples with eta / gap above 2")
        put("cnCg$(M)N", string(length(r)), "$k: samples kept")
        put("cnCg$(M)Med", sig(q(r, 0.5)), "$k: eta / gap, median")
        put("cnCg$(M)Max", sig(r[end]), "$k: eta / gap, largest")
        put("cnCg$(M)Min", sig(r[1]), "$k: eta / gap, smallest")
    end
    sort!(all_r)
    put("cnCgRaw", string(raw), "samples before dedup and the gap floor, all experiments")
    put("cnCgDup", string(raw - uniq), "repeated (gap, eta) pairs removed, all experiments")
    put("cnCgUniq", string(uniq), "distinct samples before the gap floor, all experiments")
    put("cnCgN", string(length(all_r)), "samples kept, all experiments")
    put("cnCgDropped", string(uniq - length(all_r)), "distinct samples dropped by the gap floor")
    put("cnCgBand", string(round(Int, 100 * count(r -> 1.2 <= r <= 2, all_r) / length(all_r))), "percent of kept samples with eta / gap in [1.2, 2]")
    put("cnCgBelow", string(below), "kept samples with eta below the true gap (must be 0)")
    put("cnCgMin", sig(all_r[1]), "eta / gap, smallest over every kept sample")
    put("cnCgMed", sig(q(all_r, 0.5)), "eta / gap, median over every kept sample")
    put("cnCgPnn", sig(q(all_r, 0.99)), "eta / gap, 99th percentile over every kept sample")
    put("cnCgMax", sig(all_r[end]), "eta / gap, largest over every kept sample")
    put("cnCgAboveTwo", sig(100 * count(>(2), all_r) / length(all_r); n = 2), "percent of kept samples with eta / gap above 2")
    out = joinpath(root, "preamble", "numbers_certgap.tex")
    write(out, join(lines, "\n") * "\n"); println("wrote ", out)
end

if abspath(PROGRAM_FILE) == @__FILE__
    write_certgap_numbers()
end
